&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:30,&amp;quot;335559739&amp;quot;:30}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 117, 219);&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Reasons to join our Team:&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Opportunity to be a part of a well-established, high-performance company that has been in business for over 30+ years&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:30,&amp;quot;335559739&amp;quot;:30}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
